c=cell
def H(s,ur,en,ps): add(s,f'h{len(s["paras"])+1}',en,ur,ps,kind='heading')
def P(s,ur,en,ps,**m): add(s,f'p{len(s["paras"])+1}',en,ur,ps,**m)
def V(s,ur,en,ps): P(s,ur,en,ps,boxed=True)
U='ch1e'
def Q(s,ur,en,ps,**k): add(s,f'q{len(s["paras"])+1}',en,ur,ps,role='question',exerciseId=f'ikhtiari11-{U}-q',tab='exercise',**k)
def QI(s,ur,en,ps,g): add(s,f'q{len(s["paras"])+1}',en,ur,ps,role='question',exerciseId=f'ikhtiari11-{U}-q',tab='exercise',listGroup=g)
NOTE=' English and Pashto are our translations (need native review); watermark, handwriting and ornamental borders excluded. Printed page = scan − 5 (scans from 30); printed page 24 is absent from the source.'
def fin(s,note):
    s['sourceNote']=note+NOTE; s['vocabulary']={}; save(s)
